/**
 * Referential guards shared by the service layer.
 *
 * Every id a write points at (assignee, lead, labels, parent issue, parent
 * comment) must be usable from the workspace the write is made in. A row that
 * lives in another workspace is refused as a tenant scope violation, exactly
 * like any other cross-workspace access; everything else that cannot be used
 * (missing, archived, not a current member, wrong project, nested reply) is
 * refused as not found. Callers run these before any write or event.
 */
import { TenantScopeError } from "@/lib/tenant";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import { NotFoundError } from "./_support";
import type {
  CommentId,
  IssueId,
  LabelId,
  OrgId,
  ProjectId,
  UserId,
} from "@/types/common";

/** Throws unless `userId` is a current (not removed) member of `orgId`. */
export async function assertCurrentMember(
  orgId: OrgId,
  userId: UserId,
  entity = "Member",
): Promise<void> {
  const member = await memberRepo.findMember(orgId, userId);
  if (!member) throw new NotFoundError(entity, userId);
}

/** Throws unless every label id is one of the workspace's own labels. */
export async function assertLabelsUsable(
  orgId: OrgId,
  labelIds: readonly LabelId[],
): Promise<void> {
  if (labelIds.length === 0) return;

  const owners = await labelRepo.findLabelOrgIds(labelIds);
  let missing: LabelId | null = null;

  for (const labelId of labelIds) {
    const owner = owners.get(labelId);
    if (owner === undefined) {
      missing ??= labelId;
      continue;
    }
